#include "tokens.hpp"

namespace {
	bool is_digit(int c)
	{
		return (c >= '0') && (c <= '9');
	}
	bool is_hex(int c)
	{
		return is_digit(c) || ((c >= 'a') && (c <= 'f')) || ((c >= 'A') && (c <= 'F'));
	}
	bool is_ident_start(int c)
	{
		return ((c >= 'a') && (c <= 'z')) || ((c >= 'A') && (c <= 'Z')) || (c == '_') || (c >= 0x80);
	}
	bool is_ident(int c)
	{
		return is_ident_start(c) || is_digit(c);
	}
} // namespace

std::string blitz::tools::lower(std::string_view text)
{
	std::string out(text);
	for (auto& c : out) {
		if ((c >= 'A') && (c <= 'Z')) {
			c = char(c - 'A' + 'a');
		}
	}
	return out;
}

std::string blitz::tools::join(std::vector<token> const& tokens)
{
	std::string out;
	for (auto const& token : tokens) {
		out += token.text;
	}
	return out;
}

// The rules for numbers, names and the two-character symbols are the compiler's (code_compiler/source/lexer.cpp), so that
// both split a program into the same pieces. Only white space, comments and the exact spelling are kept here.
std::vector<blitz::tools::token> blitz::tools::tokenize(std::string_view data)
{
	std::vector<token> tokens;
	size_t             at       = 0;
	size_t             text_end = size_t(-1); // Where the last name ended, to tell `Name$` apart from `$Hex`.

	auto chr = [&](size_t off = 0) -> int { return (at + off < data.size()) ? (unsigned char)data[at + off] : -1; };
	auto emit = [&](kind type, size_t start) { tokens.push_back(token{ type, std::string(data.substr(start, at - start)) }); };

	while (at < data.size()) {
		int    c     = chr();
		size_t start = at;

		if ((c == ' ') || (c == '\t')) {
			while ((chr() == ' ') || (chr() == '\t')) {
				at++;
			}
			emit(kind::space, start);
		} else if ((c == '\r') || (c == '\n')) {
			at++;
			if ((c == '\r') && (chr() == '\n')) {
				at++;
			}
			emit(kind::newline, start);
		} else if (c == ';') {
			while ((chr() != -1) && (chr() != '\r') && (chr() != '\n')) {
				at++;
			}
			emit(kind::comment, start);
		} else if (c == ':') {
			at++;
			emit(kind::separator, start);
		} else if (c == '"') {
			// No escape sequences: A string ends at the next quote, or with the line.
			at++;
			while ((chr() != '"') && (chr() != -1) && (chr() != '\r') && (chr() != '\n')) {
				at++;
			}
			if (chr() == '"') {
				at++;
			}
			emit(kind::string, start);
		} else if (is_digit(c) || ((c == '.') && is_digit(chr(1)))) {
			bool real = false;
			if ((c == '0') && ((chr(1) == 'x') || (chr(1) == 'X'))) {
				at += 2;
				while (is_hex(chr())) {
					at++;
				}
			} else if ((c == '0') && ((chr(1) == 'b') || (chr(1) == 'B'))) {
				at += 2;
				while ((chr() == '0') || (chr() == '1')) {
					at++;
				}
			} else {
				while (is_digit(chr())) {
					at++;
				}
				if ((chr() == '.') && (is_digit(chr(1)) || !is_ident_start(chr(1)))) {
					real = true;
					at++;
					while (is_digit(chr())) {
						at++;
					}
				}
			}
			if (!real && ((chr() == 'u') || (chr() == 'U'))) {
				at++;
			}
			emit(kind::number, start);
		} else if (is_ident_start(c)) {
			while (is_ident(chr())) {
				at++;
			}
			// The type character is part of the name: a%, a#, a$.
			if ((chr() == '%') || (chr() == '#') || (chr() == '$')) {
				at++;
			} else if (chr() == '*') {
				// `p*` is a Pointer, `a*b` a multiplication: like the compiler's parser, the `*` is part of the name unless an operand
				// follows it, or the name is the one that a declaration introduces.
				size_t after = 1;
				while ((chr(after) == ' ') || (chr(after) == '\t')) {
					after++;
				}
				int  n       = chr(after);
				bool operand = is_ident(n) || (n == '(') || (n == '-') || (n == '+') || (n == '~') || (n == '"') || (n == '.') || (n == '$') || (n == '%');
				bool declared = false;
				for (size_t i = tokens.size(); i-- > 0;) {
					if (tokens[i].type == kind::space) {
						continue;
					}
					if (tokens[i].type == kind::word) {
						auto word = lower(tokens[i].text);
						declared  = (word == "function") || (word == "local") || (word == "global") || (word == "field") || (word == "const") || (word == "dim");
					}
					break;
				}
				if (!operand || declared) {
					at++;
				}
			}
			text_end = at;
			emit(kind::word, start);
		} else if (((c == '$') && is_hex(chr(1)) && (at != text_end)) || ((c == '%') && ((chr(1) == '0') || (chr(1) == '1')) && (at != text_end))) {
			bool hex = (c == '$');
			at++;
			while (hex ? is_hex(chr()) : ((chr() == '0') || (chr() == '1'))) {
				at++;
			}
			if (hex && (chr() == '$')) {
				at++; // A stray type character behind the number, which Blitz allows.
			}
			emit(kind::number, start);
		} else if ((c < 32) || (c == 127)) {
			at++;
			emit(kind::other, start);
		} else {
			int next = chr(1);
			if (((c == '=') && ((next == '>') || (next == '<') || (next == '='))) || ((c == '>') && ((next == '<') || (next == '='))) || ((c == '<') && ((next == '>') || (next == '='))) || ((c == '%') && (next == '%')) || ((c == '#') && (next == '#'))) {
				at += 2;
			} else {
				at++;
			}
			emit(kind::symbol, start);
		}
	}
	return tokens;
}
